import{_ as o,o as r,c as a,a0 as e}from"./chunks/framework.D7EjqxMK.js";const _=JSON.parse('{"title":"ROS 2 工程实践（模块四）README","description":"","frontmatter":{},"headers":[],"relativePath":"08-ros/04_工程实践/README.md","filePath":"08-ros/04_工程实践/README.md"}'),d={name:"08-ros/04_工程实践/README.md"};function s(l,t,n,i,h,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="ros-2-工程实践-模块四-readme" tabindex="-1">ROS 2 工程实践（模块四）README <a class="header-anchor" href="#ros-2-工程实践-模块四-readme" aria-label="Permalink to &quot;ROS 2 工程实践（模块四）README&quot;">​</a></h1><p>本模块是 ROS 2 知识库的<strong>工程实践</strong>篇，回答&quot;如何把 ROS 2 代码变成可量产、可维护、可定位故障的机器人系统&quot;。与前三个模块（概念/核心/高级）偏&quot;原理&quot;不同，本模块全部围绕<strong>可执行的工具链、真实包名、工程决策与故障 playbook</strong>展开。</p><p><strong>前置要求</strong>：已完成 <a href="./../01_基础概念/">模块一·基础概念</a>、<a href="./../02_核心模块/">模块二·核心模块</a> 学习 <strong>难度</strong>：⭐⭐⭐（工程进阶）</p><hr><h2 id="目录与学习顺序" tabindex="-1">目录与学习顺序 <a class="header-anchor" href="#目录与学习顺序" aria-label="Permalink to &quot;目录与学习顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>文档</th><th>主题</th><th>难度</th></tr></thead><tbody><tr><td>01</td><td><a href="./01_ROS2应用架构设计模式.html">ROS2 应用架构设计模式</a></td><td>分层架构、节点粒度、接口契约、故障隔离</td><td>⭐⭐⭐</td></tr><tr><td>02</td><td><a href="./02_ROS2测试体系.html">ROS2 测试体系</a></td><td>测试金字塔、gtest/pytest、launch_testing、CI</td><td>⭐⭐⭐</td></tr><tr><td>03</td><td><a href="./03_诊断监控与故障定位.html">诊断监控与故障定位</a></td><td>日志/诊断/可视化、故障 playbook、性能剖析</td><td>⭐⭐⭐</td></tr><tr><td>04</td><td><a href="./04_持续构建发布与部署.html">持续构建发布与部署</a></td><td>colcon→bloom→构建农场→apt/Docker 部署</td><td>⭐⭐⭐</td></tr><tr><td>05</td><td><a href="./05_导航与运动控制栈(Nav2_MoveIt2_ros2control).html">导航与运动控制栈</a></td><td>Nav2 / MoveIt 2 / ros2_control 三栈协同</td><td>⭐⭐⭐</td></tr><tr><td>06</td><td><a href="./06_仿真与硬件生态.html">仿真与硬件生态</a></td><td>仿真器选型、硬件分层、sim-to-real</td><td>⭐⭐</td></tr></tbody></table><p><strong>建议学习顺序：01 → 02 → 03 → 04 → 05 → 06</strong></p><ul><li><strong>01→03</strong> 构成&quot;架构 → 测试 → 监控&quot;的软件工程闭环，是前四篇的主线。</li><li><strong>04</strong> 是工程化交付（构建/发布/部署），承接 02 的 CI。</li><li><strong>05、06</strong> 是机器人垂直领域（导航/机械臂/控制、仿真/硬件），在 01-04 的工程地基之上展开。</li></ul><hr><h2 id="知识图谱位置" tabindex="-1">知识图谱位置 <a class="header-anchor" href="#知识图谱位置" aria-label="Permalink to &quot;知识图谱位置&quot;">​</a></h2><ul><li><strong>前序模块</strong>：<a href="./../01_基础概念/">模块一·基础概念</a> → <a href="./../02_核心模块/">模块二·核心模块</a> → <a href="./../03_高级话题/">模块三·高级话题</a></li><li><strong>本模块</strong>：04_工程实践（当前）</li><li><strong>后续模块</strong>：<a href="./../05_前沿趋势/">模块五·前沿趋势</a></li></ul><hr><h2 id="模块要点速览" tabindex="-1">模块要点速览 <a class="header-anchor" href="#模块要点速览" aria-label="Permalink to &quot;模块要点速览&quot;">​</a></h2><ol><li><strong>架构设计</strong>（01）：进程边界 = 故障域 + 资源域；消息是模块间唯一契约；进程隔离 + lifecycle + supervisor 三层容错。</li><li><strong>测试</strong>（02）：单元测纯库、集成测契约（含 QoS）、仿真回归放 CI 夜间。</li><li><strong>监控定位</strong>（03）：先拓扑→再契约→后数据流；话题无数据先查 QoS；executor 阻塞是&quot;节点卡死&quot;头号原因。</li><li><strong>发布部署</strong>（04）：colcon→lint/pre-commit→action-ros-ci→bloom→build.ros2.org→index.ros.org→apt/Docker；量产锁 distro。</li><li><strong>三栈协同</strong>（05）：Nav2 出 <code>cmd_vel</code>、MoveIt 2 出关节轨迹、ros2_control 统一翻译成硬件指令；仿真换真机只换 hardware_plugin。</li><li><strong>仿真硬件</strong>（06）：GZ Sim（开源通用）/Isaac Sim（视觉高保真）/Webots（教学）；x86/Jetson/MCU 三层各司其职。</li></ol><hr><h2 id="引用与验证约定" tabindex="-1">引用与验证约定 <a class="header-anchor" href="#引用与验证约定" aria-label="Permalink to &quot;引用与验证约定&quot;">​</a></h2><p>本模块所有 URL 均经 web_search 核实，正文标注 ✅（已验证）或 ⚠️（待验证）。ROS 2 官方文档以 <strong>Jazzy</strong> 为主（<a href="https://docs.ros.org/en/jazzy/" target="_blank" rel="noreferrer">https://docs.ros.org/en/jazzy/</a>）；Nav2 现行文档域名为 <code>docs.nav2.org</code>，MoveIt 2 为 <code>moveit.picknik.ai</code>，ros2_control 为 <code>control.ros.org</code>。命名规范、消息版本化等无官方强制文档的内容，已明确标注为&quot;社区工程惯例&quot;。</p>',17)])])}const u=o(d,[["render",s]]);export{_ as __pageData,u as default};
